Action.Str:
(function () {
  function array(v) { return typeof v === 'undefined' || v === null || v === '' ? [] : Array.isArray(v) ? v : [v]; }
  function norm(v) { return String(v === null || typeof v === 'undefined' ? '' : v).trim().toLowerCase(); }
  function strictMeet() {
    var packages = array(typeof anpackage === 'undefined' ? undefined : anpackage);
    var categories = array(typeof ancategoryname === 'undefined' ? undefined : ancategoryname);
    var persistent = array(typeof anpersistent === 'undefined' ? undefined : anpersistent);
    var button1 = array(typeof anbutton1text === 'undefined' ? undefined : anbutton1text);
    var count = Math.max(packages.length, categories.length, persistent.length, button1.length);
    for (var i = 0; i < count; i++) {
      if (norm(packages[i]) === 'com.google.android.apps.tachyon' && norm(categories[i]) === 'ongoing call' && (norm(persistent[i]) === 'true' || norm(persistent[i]) === '1') && norm(button1[i]) === 'hang up') return true;
    }
    return false;
  }
  function token() { return String(Date.now()) + '-' + Math.random().toString(36).slice(2); }
  var state = String(global('MRM_STATE') || 'IDLE');
  var queryOk = norm(typeof anqueryok === 'undefined' ? undefined : anqueryok);
  if (queryOk.indexOf('1') === -1 && queryOk.indexOf('true') === -1) {
    if (state !== 'IDLE') {
      setGlobal('MRM_STATE', 'ATTENTION');
      setGlobal('MRM_ERROR', 'QUERY_FAILED');
      setGlobal('MRM_END_TOKEN', '');
      performTask('MR Meet Attention', 100, '', '', '', false, false, '', false);
    }
  } else if (strictMeet()) {
    setGlobal('MRM_END_TOKEN', '');
    setGlobal('MRM_ERROR', '');
    if (state === 'IDLE') {
      setGlobal('MRM_SESSION', token());
      setGlobal('MRM_STATE', 'OFFERED');
      performTask('MR Meet Offer', 100, '', '', '', false, false, '', false);
    }
  } else if ((state === 'OFFERED' || state === 'STARTING' || state === 'RECORDING') && !global('MRM_END_TOKEN')) {
    var endToken = token();
    setGlobal('MRM_END_TOKEN', endToken);
    performTask('MR Meet End Check', 100, '', '', '', false, false, '', false);
  }
}());

var mr_should_launch = '0';
var mr_launch_session = '';
(function () {
  function array(v) { return typeof v === 'undefined' || v === null || v === '' ? [] : Array.isArray(v) ? v : [v]; }
  function norm(v) { return String(v === null || typeof v === 'undefined' ? '' : v).trim().toLowerCase(); }
  function strictMeet() {
    var packages = array(typeof anpackage === 'undefined' ? undefined : anpackage);
    var categories = array(typeof ancategoryname === 'undefined' ? undefined : ancategoryname);
    var persistent = array(typeof anpersistent === 'undefined' ? undefined : anpersistent);
    var button1 = array(typeof anbutton1text === 'undefined' ? undefined : anbutton1text);
    var count = Math.max(packages.length, categories.length, persistent.length, button1.length);
    for (var i = 0; i < count; i++) {
      if (norm(packages[i]) === 'com.google.android.apps.tachyon' && norm(categories[i]) === 'ongoing call' && (norm(persistent[i]) === 'true' || norm(persistent[i]) === '1') && norm(button1[i]) === 'hang up') return true;
    }
    return false;
  }
  var state = String(global('MRM_STATE') || 'IDLE');
  if (state !== 'OFFERED') return;
  var queryOk = norm(typeof anqueryok === 'undefined' ? undefined : anqueryok);
  if (queryOk.indexOf('1') === -1 && queryOk.indexOf('true') === -1) {
    setGlobal('MRM_STATE', 'ATTENTION');
    setGlobal('MRM_ERROR', 'START_QUERY_FAILED');
    setGlobal('MRM_END_TOKEN', '');
    performTask('MR Meet Attention', 100, '', '', '', false, false, '', false);
  } else if (!strictMeet()) {
    setGlobal('MRM_STATE', 'IDLE');
    setGlobal('MRM_SESSION', '');
    setGlobal('MRM_END_TOKEN', '');
    setGlobal('MRM_ERROR', 'CALL_ENDED_BEFORE_START');
  } else {
    mr_launch_session = String(global('MRM_SESSION') || '');
    if (!mr_launch_session) {
      setGlobal('MRM_STATE', 'ATTENTION');
      setGlobal('MRM_ERROR', 'START_SESSION_MISSING');
      performTask('MR Meet Attention', 100, '', '', '', false, false, '', false);
    } else {
      setGlobal('MRM_STATE', 'STARTING');
      setGlobal('MRM_ERROR', '');
      mr_should_launch = '1';
    }
  }
}());

(function () {
  if (String(typeof mr_should_launch === 'undefined' ? '' : mr_should_launch) !== '1') return;
  var session = String(typeof mr_launch_session === 'undefined' ? '' : mr_launch_session);
  if (session && String(global('MRM_STATE') || 'IDLE') === 'STARTING' && String(global('MRM_SESSION') || '') === session) {
    setGlobal('MR_ASR_ACTIVE', '1');
    setGlobal('MRM_STATE', 'RECORDING');
    setGlobal('MRM_ERROR', '');
  } else {
    setGlobal('MRM_STATE', 'ATTENTION');
    setGlobal('MRM_ERROR', 'START_TRANSITION_STALE');
    performTask('MR Meet Attention', 100, '', '', '', false, false, '', false);
  }
}());

var mr_should_stop = '0';
var mr_stop_session = '';
(function () {
  function array(v) { return typeof v === 'undefined' || v === null || v === '' ? [] : Array.isArray(v) ? v : [v]; }
  function norm(v) { return String(v === null || typeof v === 'undefined' ? '' : v).trim().toLowerCase(); }
  function strictMeet() {
    var packages = array(typeof anpackage === 'undefined' ? undefined : anpackage);
    var categories = array(typeof ancategoryname === 'undefined' ? undefined : ancategoryname);
    var persistent = array(typeof anpersistent === 'undefined' ? undefined : anpersistent);
    var button1 = array(typeof anbutton1text === 'undefined' ? undefined : anbutton1text);
    var count = Math.max(packages.length, categories.length, persistent.length, button1.length);
    for (var i = 0; i < count; i++) {
      if (norm(packages[i]) === 'com.google.android.apps.tachyon' && norm(categories[i]) === 'ongoing call' && (norm(persistent[i]) === 'true' || norm(persistent[i]) === '1') && norm(button1[i]) === 'hang up') return true;
    }
    return false;
  }
  var endToken = String(typeof mr_end_token === 'undefined' ? '' : mr_end_token);
  var endSession = String(typeof mr_end_session === 'undefined' ? '' : mr_end_session);
  var state = String(global('MRM_STATE') || 'IDLE');
  if (!endToken || !endSession || endToken !== String(global('MRM_END_TOKEN') || '') || endSession !== String(global('MRM_SESSION') || '') || (state !== 'OFFERED' && state !== 'STARTING' && state !== 'RECORDING')) return;
  var queryOk = norm(typeof anqueryok === 'undefined' ? undefined : anqueryok);
  if (queryOk.indexOf('1') === -1 && queryOk.indexOf('true') === -1) {
    setGlobal('MRM_END_TOKEN', '');
    setGlobal('MRM_STATE', 'ATTENTION');
    setGlobal('MRM_ERROR', 'END_QUERY_FAILED');
    performTask('MR Meet Attention', 100, '', '', '', false, false, '', false);
  } else if (strictMeet()) {
    setGlobal('MRM_END_TOKEN', '');
    setGlobal('MRM_ERROR', '');
  } else if (state === 'OFFERED') {
    setGlobal('MRM_STATE', 'IDLE');
    setGlobal('MRM_SESSION', '');
    setGlobal('MRM_END_TOKEN', '');
    setGlobal('MRM_ERROR', '');
    performTask('MR Meet Reset (No Stop)', 100, '', '', '', false, false, '', false);
  } else if (state === 'STARTING') {
    setGlobal('MRM_END_TOKEN', '');
    setGlobal('MRM_STATE', 'ATTENTION');
    setGlobal('MRM_ERROR', 'START_STUCK');
    performTask('MR Meet Attention', 100, '', '', '', false, false, '', false);
  } else {
    setGlobal('MRM_STATE', 'STOPPING');
    setGlobal('MRM_END_TOKEN', '');
    mr_stop_session = mr_end_session;
    mr_should_stop = '1';
  }
}());

(function () {
  function norm(v) { return String(v === null || typeof v === 'undefined' ? '' : v).trim().toLowerCase(); }
  if (String(typeof mr_should_stop === 'undefined' ? '' : mr_should_stop) !== '1') return;
  var session = String(typeof mr_stop_session === 'undefined' ? '' : mr_stop_session);
  if (!session || String(global('MRM_STATE') || 'IDLE') !== 'STOPPING' || String(global('MRM_SESSION') || '') !== session) return;
  var active = norm(global('MR_ASR_ACTIVE'));
  if (active === '' || active === '0' || active === 'false') {
    setGlobal('MRM_STATE', 'IDLE');
    setGlobal('MRM_SESSION', '');
    setGlobal('MRM_END_TOKEN', '');
    setGlobal('MRM_ERROR', '');
    performTask('MR Meet Reconcile', 100, '', '', '', false, false, '', false);
  } else {
    setGlobal('MRM_STATE', 'ATTENTION');
    setGlobal('MRM_ERROR', 'STOP_FAILED_OR_UNCONFIRMED');
    performTask('MR Meet Attention', 100, '', '', '', false, false, '', false);
  }
}());
